<?php namespace App\Http\Controllers\Api; use App\Http\Controllers\Controller; use App\Http\Requests\StoreBookingRequest; use App\Http\Resources\BookingResource; use App\Models\Booking; use App\Services\BookingService; use Illuminate\Http\Request; class BookingController extends Controller {public function store(StoreBookingRequest $r,BookingService $service){$b=$service->reserve($r->user()->id,$r->validated(),$r->header('Idempotency-Key'));return (new BookingResource($b))->response()->setStatusCode(201);}public function hold(StoreBookingRequest $r,BookingService $service){$b=$service->hold($r->user()->id,$r->validated(),$r->header('Idempotency-Key'));return (new BookingResource($b))->response()->setStatusCode(201);}public function confirm(Request $r,Booking $booking,BookingService $service){$b=$service->confirm($booking,$r->user()->id);return new BookingResource($b->load('items'));}public function index(Request $r){return BookingResource::collection(Booking::where('user_id',$r->user()->id)->with(['items','tickets'])->latest()->paginate(20));}public function show(Request $r,Booking $booking){abort_unless($booking->user_id===$r->user()->id||$r->user()->role->value==='admin',403);return new BookingResource($booking->load(['items','tickets']));}public function announcement(\App\Http\Requests\AnnouncementRequest $r,\App\Models\Event $event){$a=$event->announcements()->create(['organizer_id'=>$r->user()->id,'message'=>$r->validated('message')]);\App\Jobs\SendAnnouncementJob::dispatch($a->id)->onQueue('bulk');return response()->json(['message'=>'أُضيف الإعلان لطابور الإرسال منخفض الأولوية.','announcement_id'=>$a->id],202);}}
